    correctKey: 'A',
    explanation: '混合点は風量の多い側に引き寄せられる。外気多→外気寄りの状態。\n【図解】外気と還気の混合\n　外気点●━━━━━混合点━━━━━●還気点\n　　　　　（風量比に応じて内分）★\n　○外気風量割合大 → 混合点は外気側に近づく\n　×外気風量割合大なのに還気側に近づく、は誤り\n　→ 外気負荷計算では混合点から室内設定点までの\n　　差分をコイル負荷として求める★',
