    correctKey: 'C',
    explanation: '抵抗曲線は流量の2乗に比例する右上がりの曲線。\n【図解】ポンプ運転点の決定\n　揚程\n　│＼ポンプ曲線（右下がり）★\n　│／抵抗曲線（流量の2乗に比例・右上がり）★\n　│×＝運転点（両曲線の交点）★\n　└──────流量\n　○締切運転：吐出し量ゼロ→長時間×（過熱・焼付き）★\n×配管系の抵抗曲線は、流量に反比例する形状（右下がりの曲線）を示す。\n→抵抗曲線は流量の2乗に比例する右上がりの曲線。',
    difficulty: 'advanced',
