    correctKey: 'B',
    explanation: '積雪荷重は屋根勾配による低減係数を考慮する。\n【図解】建築物に作用する主な荷重\n　固定荷重：躯体・仕上げの自重（常時作用）\n　積載荷重：用途に応じて規定（事務室＜住宅＜倉庫等）\n　地震力：建物重量に比例して増加★\n　積雪荷重：屋根勾配による低減係数を考慮★\n　　（勾配大→積雪滑落しやすい→荷重低減）\n　風荷重：建物の形状・高さ・地域係数等で算定\n○積雪荷重は、屋根勾配が大きいほど積雪が滑落しやすいため、勾配に応じた低減係数…\n×積雪荷重は、屋根の勾配にかかわらず、一定の単位荷重を用いて計算する。\n→積雪荷重は屋根勾配による低減係数を考慮する。',
    difficulty: 'advanced',
