    explanation: 'RTはX線・γ線で内部欠陥を検出する代表的な非破壊検査。\n【図解】溶接部の検査方法の分類\n　外観検査：表面の形状・アンダーカット等（目視）\n　表面検査：浸透探傷試験（PT）・磁粉探傷試験（MT）★\n　内部検査：超音波探傷試験（UT）★・放射線透過試験（RT）★\n　　（RTは内部欠陥検出の代表的手法。「表面のみ」は誤り）\n　→ 重要部位ほど複数の検査方法を組み合わせる',
    difficulty: 'basic',
