    explanation: '低放射率仕上げの保温材は放射抑制効果も持つ。「一切ない」は言い過ぎ。\n【図解】保温材の断熱メカニズム\n　主効果：伝導・対流の抑制（低熱伝導率の材料・気泡構造）★\n　補助効果：表面のアルミ箔等 → 放射の抑制にも寄与★\n　　（「放射抑制効果が一切ない」は誤り）\n　放射暖房：床暖房・パネルヒーター（放射主体）\n　対流暖房：ファンコンベクタ（対流主体）\n○保温材は主に伝導・対流による熱移動を抑制するが、表面にアルミ箔等の低放射率仕…\n→低放射率仕上げの保温材は放射抑制効果も持つ。「一切ない」は言い過ぎ。',
    difficulty: 'advanced',
