    choices: [
      { key: 'A', text: '等摩擦法は、ダクト系全体の単位長さあたりの摩擦損失をほぼ一定に保つように各部の寸法を決定する設計法である。', explanation: '適当。実務で最も広く用いられるダクト設計法である。' },
      { key: 'B', text: '等摩擦法で設計したダクト系は、末端に近い枝ダクトほど、主ダクトに比べて相対的に静圧が過剰となりやすく、風量バランスの調整（ダンパー）が必要になることが多い。', explanation: '適当。等摩擦法は概算の初期設計に優れるが、末端の圧力バランスは別途ダンパー調整が必要になる。' },
      { key: 'C', text: '等摩擦法における単位摩擦損失の目安は、主ダクトで概ね1Pa/m程度が用いられることが多い。', explanation: '適当。低圧ダクトの設計では概ね1Pa/m前後が目安とされる。' },
      { key: 'D', text: '等摩擦法は、ダクトが分岐しても風速を一定に保つように設計する方法であり、等速法と同じ設計思想である。', explanation: '不適当。等摩擦法は「単位長さあたりの摩擦損失（圧力勾配）」を一定に保つ設計法であり、風速を一定に保つ設計法は「等速法」である。両者は異なる設計思想であり、等摩擦法では分岐が進むにつれ風量減少に応じて風速も変化する（等速法とは区別される）。' },
    ],
    correctKey: 'D',
    explanation: '等摩擦法＝圧力勾配一定、等速法＝風速一定。混同注意。\n【図解】ダクト設計法の比較\n　等摩擦法：単位長さあたりの摩擦損失をほぼ一定に保つ★\n　　（主ダクト概ね1Pa/m程度が目安）\n　等速法：ダクト内風速を一定に保つ設計法★（粉じん搬送等）\n　○末端の圧力バランス → ダンパーで別途調整が必要★\n　→ 一般空調ダクトの実務は等摩擦法が主流',
    difficulty: 'advanced',
