    explanation: 'VAVは室温に応じて風量を変えることで温度制御する方式。\n【図解】自動制御の基本動作\n　P制御：比例動作・オフセット残る\n　PI制御：比例＋積分→オフセット解消★\n　PID制御：比例＋積分＋微分→応答性向上★\n　○VAV制御：室温に応じ風量を増減させ温度制御★\n　×VAVは風量一定で温度制御しない、は誤り（CAVの説明）',
    difficulty: 'standard',
