    correctKey: 'A',
    explanation: 'クリーンルームは正圧が原則。負圧は汚染物質を漏らさない室の考え方。\n【図解】室圧管理の考え方\n　クリーンルーム（汚染流入を防ぐ）→ 正圧★\n　バイオハザード室・感染症病室（汚染流出を防ぐ）→ 負圧\n　HEPAフィルタ：0.3μm粒子で99.97%以上捕集★\n　清浄度クラスが高いほど → 換気回数を多く設定★\n○クリーンルームは周辺の一般室（清浄度の低い室）から汚染空気が流入するのを防ぐ…\n×クリーンルームは、周辺の一般室からの汚染空気の流入を防ぐため、室内を…\n→クリーンルームは正圧が原則。負圧は汚染物質を漏らさない室の考え方。',
    difficulty: 'advanced',
