    explanation: '運転方式は電主熱従・熱主電従があり、施設に応じて選択。排熱の余剰も生じ得る。\n【図解】コージェネレーションの運転方式\n　電主熱従：電力需要に合わせて発電（熱は従属）\n　熱主電従：熱需要に合わせて発電（電力は従属）\n　○総合エネルギー効率：発電のみより高い★（排熱を有効利用）\n　⚠負荷特性とのミスマッチ → 排熱の余剰・不足が生じ得る★\n　　→ 蓄熱槽等の併用で調整することがある',
    difficulty: 'advanced',
