    correctKey: 'C',
    explanation: '放射冷暖房は顕熱処理が主体。潜熱（湿度）制御は別系統との併用が必要。\n【図解】放射冷暖房方式の特徴\n　○主な処理対象：顕熱負荷★（対流式より上下温度差が小さい）\n　⚠潜熱負荷（除湿・加湿）の処理は不得意★\n　　→ 外調機・デシカント等の別系統と併用が必要★\n　結露リスク：パネル表面温度＜室内露点温度 → 結露★\n　気流感が少なく静穏性に優れる',
