    question: 'ボイラーの容量・効率に関する記述として、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: 'ボイラー効率は、投入した燃料の発熱量に対する、蒸気（または温水）が得た熱量の割合で表される。', explanation: '適当。ボイラー効率の基本定義である。' },
      { key: 'B', text: '排ガス熱を回収するエコノマイザを設置すると、給水を予熱でき、ボイラー効率の向上に寄与する。', explanation: '適当。排熱回収によるボイラー効率向上策の代表例である。' },
      { key: 'C', text: 'ボイラーの燃焼用空気量が理論空気量より過大（空気比が大きい）であるほど、一般に排ガス熱損失が減少しボイラー効率が向上する。', explanation: '不適当。燃焼用空気量が理論空気量よりも過大（空気比大）であると、燃焼に使われない余剰の空気まで加熱されて排ガスとして排出されるため、排ガス熱損失は「増加」し、ボイラー効率は「低下」する。適切な空気比（一般に1.1〜1.3程度）で運転することが効率上重要であり、空気比が大きいほど効率が向上するというのは誤りである。' },
      { key: 'D', text: 'ボイラーの缶体・配管からの放熱損失を低減するため、断熱・保温を適切に施すことが効率向上に寄与する。', explanation: '適当。放熱損失の低減も効率向上策の一つである。' },
    ],
    correctKey: 'C',
