    explanation: '粉末消火は冷却効果に乏しく、再燃防止の観点では他の消火剤より劣るとされる。\n【図解】消火設備ごとの消火メカニズム\n　水噴霧：冷却＋窒息効果★（油火災にも一定の適性）\n　粉末：負触媒効果（燃焼の連鎖反応を抑制）★\n　　⚠冷却効果に乏しく再燃リスクは他方式より高い★\n　　（「再燃防止に優れる」は誤り・弱点として問われやすい）\n　→ 用途に応じ消火剤の特性（冷却・窒息・負触媒）を選定',
    difficulty: 'advanced',
