    explanation: 'ガソリン等は揮発性・引火性が高く、分離後は適切な回収・処理が必要。\n【図解】オイル阻集器の役割\n　対象：駐車場・洗車場・給油所等の油分含有排水★\n　原理：比重差分離（グリース阻集器と共通）★\n　⚠分離した油分：揮発性・引火性が高い★\n　　→ 適切な回収・処理が必要（放流厳禁）★\n　　（下水道内での火災・爆発の危険を防止）\n○オイル阻集器で分離される油分（ガソリン・軽油等）は揮発性・引火性が高く、その…\n×オイル阻集器で分離されたガソリン等の油分は、揮発性・引火性がないため…',
    difficulty: 'advanced',
