    question: 'ネットワーク工程表の日程計算に関する記述として、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: '最早開始時刻（EST）は、先行するすべての作業が完了した後、その作業を開始できる最も早い時刻である。', explanation: '適当。前進計算により算出される基本概念である。' },
      { key: 'B', text: '最遅完了時刻（LFT）は、全体工期に影響を与えることなく、その作業を完了させることが許される最も遅い時刻である。', explanation: '適当。後進計算により算出される基本概念である。' },
      { key: 'C', text: 'ある作業のトータルフロートがゼロである場合、その作業はクリティカルパス上にある可能性が高い。', explanation: '適当。フロートゼロの作業がクリティカルパスを構成する。' },
      { key: 'D', text: 'ある作業の最早開始時刻（EST）は、後続作業の最遅完了時刻（LFT）を求めることで算出される。', explanation: '不適当。最早開始時刻（EST）は、その作業に「先行する」作業の最早完了時刻（EFT）の中で最大のものを求める「前進計算」によって算出される。一方、最遅完了時刻（LFT）は、その作業に「後続する」作業の最遅開始時刻（LST）の中で最小のものを求める「後進計算」によって算出される。ESTを後続作業のLFTから求めるという記述は、前進計算と後進計算の関係を混同した誤りである。' },
    ],
    correctKey: 'D',
