    correctKey: 'A',
    explanation: '総合図・施工図は設計変更・現場条件変化に応じて随時修正・改訂される。\n【図解】総合図・施工図の役割\n　総合図：複数工種を重ね合わせ天井内等の納まりを事前調整★\n　施工図：設計図をもとに詳細寸法・納まりを明示★\n　○輻輳箇所の事前調整により手戻りリスクを低減★\n　×「承認後は修正不要」は実務と乖離した誤り★\n　　（設計変更・現場条件変化に応じ改訂が必要）',
    difficulty: 'advanced',
