    explanation: '停電作業でも検電の実施は必須。記録のみに頼るのは危険。\n【図解】感電災害防止の基本\n　○仮設配線：被覆損傷・水濡れの点検管理★\n　○活線近接作業：絶縁用保護具・資格確認★\n　○仮設分電盤：漏電遮断器の設置★\n　⚠停電作業：作業前の検電が必須★\n　　（記録のみに頼るのは重大な誤り・逆送電等の見逃しリスク）',
