    question: '建築基準法上の居室の採光・換気規定に関する記述として、誤っているものはどれか。',
    choices: [
      { key: 'A', text: '住宅の居室には、原則として床面積に対して一定割合以上の採光に有効な開口部を設けなければならない。', explanation: '正しい。採光規定の基本である。' },
      { key: 'B', text: '居室には、原則としてその居室の床面積に対して20分の1以上の換気に有効な開口部を設けなければならず、機械換気設備を設ける場合であっても、この開口部を省略することはできない。', explanation: '誤り（本問の正解）。居室には床面積の20分の1以上の換気上有効な開口部を設けるのが原則であるが、規定の技術基準に適合する換気設備（機械換気設備等）を設けた場合には、この開口部を設けないことができる。「省略できない」は誤り。' },
      { key: 'C', text: '便所には、原則として直接外気に接する窓を設けなければならないが、水洗便所で一定の換気設備を設けた場合は窓を設けないことができる。', explanation: '正しい。水洗便所かつ換気設備があれば窓は不要となる。' },
      { key: 'D', text: 'シックハウス対策として、居室には原則としてホルムアルデヒドの発散に対応した機械換気設備の設置が義務付けられている。', explanation: '正しい。24時間換気設備の設置義務の根拠である。' },
    ],
    correctKey: 'B',
    explanation: '技術基準に適合する機械換気設備があれば開口部を省略できる。\n【図解】居室の採光・換気\n　採光：居室の床面積に対する採光有効開口部の割合を規定★\n　換気：床面積の20分の1以上の換気上有効な開口部が原則★\n　　→ 技術基準適合の機械換気設備があれば省略可★\n　便所：水洗＋換気設備があれば外気に接する窓は不要',
    difficulty: 'standard',
