    explanation: '36協定があっても時間外労働には上限規制（原則月45時間・年360時間等）が適用される。\n【図解】時間外労働の規制\n　36協定：時間外・休日労働の前提として締結・届出★\n　上限規制：原則月45時間・年360時間★（臨時的特別条項でも上限あり）\n　割増賃金：時間外・休日・深夜労働で法定割増率適用★\n　×「36協定があれば上限規制なし」は誤り★\n○36協定を締結・届出した場合であっても、時間外労働の時間数には、臨時的な特別…\n→36協定があっても時間外労働には上限規制（原則月45時間・年360時間等）が適用…',
    difficulty: 'standard',
