    explanation: '施工体制台帳は記載事項に変更が生じた都度、遅滞なく変更する必要がある。\n【図解】施工体制台帳・再下請負通知\n　作成義務：特定建設業者が一定額以上の下請契約を締結する場合★\n　再下請負通知：下請負人から元請への通知義務★\n　発注者への閲覧：請求があれば供する義務★\n　×「変更は次の更新時期まででよい」は誤り★\n　　（変更の都度、遅滞なく修正する必要）\n○施工体制台帳の作成が義務付けられる工事において、記載事項に変更が生じた場合（…\n→施工体制台帳は記載事項に変更が生じた都度、遅滞なく変更する必要がある。',
